// Sound effects that follow the camera. The renderer reports what each shot shows (cues); this module
// places matching sounds on a 30 s stereo track: hammering and sawing on new houses, anvil and fire at the
// forge, water and oars at the dock, bells at the chapel, chains when the drawbridge moves, birds overall.
// Every sound is synthesized here (CC0, generated by this repository) unless a file with the same name
// exists in assets/audio/sfx/ (e.g. hammer.wav, water.ogg) — then that recording is used instead.
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { rng } from '../sim/prng.js';
import { writeWav, readWav } from './wav.js';

export const RATE = 48000;
const TAU = Math.PI * 2;

// ------------------------------------------------------------------ DSP helpers
class Biquad {
  constructor(type, f, q = 0.7) {
    this.x1 = this.x2 = this.y1 = this.y2 = 0;
    this.set(type, f, q);
  }
  set(type, f, q = 0.7) {
    const w = (TAU * f) / RATE, c = Math.cos(w), s = Math.sin(w), a = s / (2 * q);
    let b0, b1, b2, a0, a1, a2;
    if (type === 'lp') { b0 = (1 - c) / 2; b1 = 1 - c; b2 = b0; }
    else if (type === 'hp') { b0 = (1 + c) / 2; b1 = -(1 + c); b2 = b0; }
    else { b0 = a; b1 = 0; b2 = -a; } // band-pass (0 dB peak)
    a0 = 1 + a; a1 = -2 * c; a2 = 1 - a;
    Object.assign(this, { b0: b0 / a0, b1: b1 / a0, b2: b2 / a0, a1: a1 / a0, a2: a2 / a0 });
  }
  run(x) {
    const y = this.b0 * x + this.b1 * this.x1 + this.b2 * this.x2 - this.a1 * this.y1 - this.a2 * this.y2;
    this.x2 = this.x1; this.x1 = x; this.y2 = this.y1; this.y1 = y;
    return y;
  }
}
const buf = (sec) => new Float32Array(Math.max(1, Math.round(sec * RATE)));
function modes(out, at, partials, amp, r) {
  // modal synthesis: decaying sinusoids [freq, gain, decay]
  for (const [f, g, d] of partials) {
    const ph = r.float(0, TAU);
    const len = Math.min(out.length - at, Math.round((d * 5) * RATE));
    for (let i = 0; i < len; i++) out[at + i] += Math.sin(ph + (TAU * f * i) / RATE) * g * amp * Math.exp(-i / RATE / d);
  }
}
function noiseBurst(out, at, dur, amp, r, filt) {
  const len = Math.min(out.length - at, Math.round(dur * RATE));
  for (let i = 0; i < len; i++) {
    const env = Math.exp(-i / RATE / (dur / 4));
    let v = r.float(-1, 1);
    for (const f of filt) v = f.run(v);
    out[at + i] += v * env * amp;
  }
}

// ------------------------------------------------------------------ sound generators (mono, seconds)
const GEN = {
  hammer(sec, r) { // nails into timber: bursts of 3-6 knocks
    const o = buf(sec);
    let t = r.float(0.05, 0.4);
    while (t < sec - 0.3) {
      const n = r.int(3, 6), base = r.float(380, 520), gap = r.float(0.32, 0.45);
      for (let k = 0; k < n && t < sec - 0.2; k++, t += gap * r.float(0.9, 1.1)) {
        const at = Math.round(t * RATE), a = r.float(0.5, 0.8) * (k === n - 1 ? 1.15 : 1);
        modes(o, at, [[base, 0.6, 0.035], [base * 2.31, 0.35, 0.02], [base * 4.1, 0.2, 0.012], [base * 0.52, 0.5, 0.05]], a, r);
        noiseBurst(o, at, 0.012, a * 0.6, r, [new Biquad('bp', 2500, 1.2)]);
      }
      t += r.float(0.8, 2.2);
    }
    return o;
  },
  saw(sec, r) { // hand saw strokes
    const o = buf(sec);
    const bp = new Biquad('bp', 3200, 1.4), bp2 = new Biquad('bp', 1600, 2);
    let t = r.float(0, 0.5);
    while (t < sec - 0.6) {
      const strokes = r.int(4, 9), len = r.float(0.38, 0.5);
      for (let k = 0; k < strokes && t < sec - 0.5; k++, t += len) {
        const at = Math.round(t * RATE), n = Math.round(len * RATE * 0.92), push = k % 2 === 0;
        for (let i = 0; i < n && at + i < o.length; i++) {
          const x = i / n, env = Math.sin(Math.PI * x) ** 1.5 * (push ? 1 : 0.7);
          const teeth = 0.55 + 0.45 * Math.sin((TAU * (push ? 55 : 48) * i) / RATE);
          const v = r.float(-1, 1);
          o[at + i] += (bp.run(v) * 1.4 + bp2.run(v) * 0.6) * env * teeth * 0.5;
        }
      }
      t += r.float(1.2, 2.8);
    }
    return o;
  },
  anvil(sec, r) { // smith's hammer on the anvil: ring, ring, pause
    const o = buf(sec);
    let t = r.float(0.1, 0.6);
    while (t < sec - 0.4) {
      for (let k = 0; k < r.int(2, 4) && t < sec - 0.3; k++, t += r.float(0.42, 0.55)) {
        const at = Math.round(t * RATE), f = r.float(1050, 1180), a = r.float(0.35, 0.5);
        modes(o, at, [[f, 0.5, 0.45], [f * 2.76, 0.32, 0.22], [f * 5.4, 0.18, 0.1], [f * 8.93, 0.1, 0.05], [f * 0.5, 0.15, 0.3]], a, r);
        noiseBurst(o, at, 0.01, a, r, [new Biquad('hp', 3000)]);
      }
      t += r.float(0.9, 1.8);
    }
    return o;
  },
  fire(sec, r) { // crackle over a soft roar
    const o = buf(sec);
    const lp = new Biquad('lp', 420), lp2 = new Biquad('lp', 300);
    for (let i = 0; i < o.length; i++) o[i] = lp2.run(lp.run(r.float(-1, 1))) * 0.9;
    for (let k = 0; k < sec * 14; k++) noiseBurst(o, Math.round(r.float(0, sec - 0.05) * RATE), r.float(0.004, 0.02), r.float(0.1, 0.45), r, [new Biquad('bp', r.float(1500, 5000), 1.5)]);
    return o;
  },
  water(sec, r) { // gentle lapping against posts and the bank
    const o = buf(sec);
    const lp = new Biquad('lp', 900), bp = new Biquad('bp', 450, 0.8);
    let ph = r.float(0, TAU);
    for (let i = 0; i < o.length; i++) {
      ph += (TAU * (0.55 + 0.2 * Math.sin(i / RATE / 3))) / RATE;
      const swell = 0.35 + 0.65 * Math.max(0, Math.sin(ph)) ** 2;
      const v = r.float(-1, 1);
      o[i] = (lp.run(v) * 0.6 + bp.run(v) * 0.9) * swell * 0.7;
    }
    // little plops and bubbles
    for (let k = 0; k < sec * 2.5; k++) {
      const at = Math.round(r.float(0, sec - 0.2) * RATE), f0 = r.float(500, 1100), len = Math.round(r.float(0.04, 0.09) * RATE);
      let p = 0;
      for (let i = 0; i < len && at + i < o.length; i++) { p += (TAU * f0 * (1 + (i / len) * 1.2)) / RATE; o[at + i] += Math.sin(p) * Math.sin((Math.PI * i) / len) * 0.12; }
    }
    return o;
  },
  oars(sec, r) { // oar strokes: splash then drip
    const o = buf(sec);
    for (let t = r.float(0.3, 1); t < sec - 0.5; t += r.float(1.8, 2.6)) {
      noiseBurst(o, Math.round(t * RATE), 0.35, 0.5, r, [new Biquad('bp', 1200, 0.7), new Biquad('lp', 3000)]);
      for (let d = 0; d < 4; d++) {
        const at = Math.round((t + 0.5 + d * 0.13) * RATE), len = Math.round(0.05 * RATE), f0 = r.float(900, 1500);
        let p = 0;
        for (let i = 0; i < len && at + i < o.length; i++) { p += (TAU * f0 * (1 + i / len)) / RATE; o[at + i] += Math.sin(p) * Math.sin((Math.PI * i) / len) * 0.15; }
      }
    }
    return o;
  },
  bell(sec, r) { // a church bell, a few slow tolls
    const o = buf(sec);
    const f = r.float(260, 330);
    for (let t = 0.2; t < sec - 1; t += 2.6) modes(o, Math.round(t * RATE), [[f * 0.5, 0.5, 2.2], [f, 0.6, 1.6], [f * 1.19, 0.4, 1.2], [f * 1.5, 0.35, 1.0], [f * 2.0, 0.3, 0.8], [f * 2.52, 0.2, 0.5], [f * 3.0, 0.12, 0.4]], 0.32, r);
    return o;
  },
  chisel(sec, r) { // mason's chisel and mallet on stone
    const o = buf(sec);
    for (let t = r.float(0.1, 0.4); t < sec - 0.2; t += r.float(0.35, 0.6) + (r.chance(0.2) ? 1.2 : 0)) {
      const at = Math.round(t * RATE), f = r.float(2900, 3600);
      modes(o, at, [[f, 0.4, 0.05], [f * 1.63, 0.25, 0.03], [f * 0.41, 0.3, 0.02]], 0.45, r);
      noiseBurst(o, at, 0.03, 0.35, r, [new Biquad('bp', 1800, 0.9)]);
    }
    return o;
  },
  stone(sec, r) { // heavy blocks set down
    const o = buf(sec);
    for (let t = r.float(0.4, 1.2); t < sec - 0.4; t += r.float(2.2, 4)) {
      const at = Math.round(t * RATE);
      modes(o, at, [[62, 0.9, 0.12], [118, 0.5, 0.08], [240, 0.25, 0.04]], 0.7, r);
      noiseBurst(o, at, 0.18, 0.4, r, [new Biquad('lp', 900)]);
    }
    return o;
  },
  chain(sec, r) { // drawbridge chains running over the windlass
    const o = buf(sec);
    for (let t = 0; t < sec; t += r.float(0.018, 0.05)) {
      const at = Math.round(t * RATE), f = r.float(2200, 4200), a = 0.12 + 0.12 * Math.sin((Math.PI * t) / sec);
      modes(o, at, [[f, 0.5, 0.025], [f * 1.7, 0.3, 0.015]], a, r);
    }
    // the windlass ratchet clacks
    for (let t = 0.05; t < sec; t += 0.16) modes(o, Math.round(t * RATE), [[700, 0.4, 0.02], [1650, 0.3, 0.012]], 0.35, r);
    return o;
  },
  thud(sec, r) { // a single heavy wooden thud (drawbridge landing, roof beam set)
    const o = buf(sec);
    modes(o, 0, [[55, 1, 0.18], [95, 0.6, 0.12], [210, 0.3, 0.05]], 0.9, r);
    noiseBurst(o, 0, 0.12, 0.5, r, [new Biquad('lp', 700)]);
    return o;
  },
  creak(sec, r) { // wooden sails and beams creaking
    const o = buf(sec);
    for (let t = r.float(0.2, 0.8); t < sec - 0.8; t += r.float(1.5, 3)) {
      const at = Math.round(t * RATE), len = Math.round(r.float(0.4, 0.8) * RATE), bp = new Biquad('bp', r.float(700, 1100), 4);
      let ph = 0, f0 = r.float(70, 120);
      for (let i = 0; i < len && at + i < o.length; i++) {
        const x = i / len;
        ph += (TAU * f0 * (1 + 0.6 * x + 0.05 * r.float(-1, 1))) / RATE;
        o[at + i] += bp.run((ph % TAU) / TAU - 0.5) * Math.sin(Math.PI * x) * 1.8;
      }
    }
    return o;
  },
  cart(sec, r) { // a cart rolling on packed earth
    const o = buf(sec);
    const lp = new Biquad('lp', 220);
    for (let i = 0; i < o.length; i++) o[i] = lp.run(r.float(-1, 1)) * 1.6 * Math.min(1, i / RATE / 0.8) * Math.min(1, (o.length - i) / RATE / 0.8);
    for (let t = 0.1; t < sec; t += r.float(0.18, 0.3)) modes(o, Math.round(t * RATE), [[160, 0.4, 0.03], [420, 0.2, 0.015]], 0.25, r);
    return o;
  },
  chatter(sec, r) { // distant market chatter: babbling formant voices, kept soft
    const o = buf(sec);
    const voices = 7;
    for (let v = 0; v < voices; v++) {
      const f0 = r.float(95, 230), f1 = new Biquad('bp', 600, 3), f2 = new Biquad('bp', 1500, 4);
      let ph = 0, syll = 0, sylLen = 0, amp = 0, target = 0, i0 = Math.round(r.float(0, 1) * RATE);
      for (let i = i0; i < o.length; i++) {
        if (--syll <= 0) {
          sylLen = syll = Math.round(r.float(0.09, 0.22) * RATE);
          target = r.chance(0.18) ? 0 : r.float(0.4, 1);
          f1.set('bp', r.float(350, 850), 3);
          f2.set('bp', r.float(1000, 2300), 4);
        }
        amp += (target - amp) * 0.002;
        ph += (TAU * f0 * (1 + 0.04 * Math.sin(i / 3000))) / RATE;
        const src = (ph % TAU) / TAU - 0.5;
        o[i] += (f1.run(src) + 0.5 * f2.run(src)) * amp * 0.35 * Math.sin((Math.PI * (sylLen - syll)) / sylLen);
      }
    }
    const lp = new Biquad('lp', 2200);
    for (let i = 0; i < o.length; i++) o[i] = lp.run(o[i]);
    return o;
  },
  birds(sec, r) { // songbirds: trills and whistles, sparse
    const o = buf(sec);
    for (let k = 0; k < sec * 0.9; k++) {
      const st = r.float(0, sec - 1.2), kind = r.int(0, 2), f0 = r.float(2400, 4600);
      const notes = kind === 0 ? r.int(4, 9) : r.int(2, 4);
      for (let j = 0; j < notes; j++) {
        const at = Math.round((st + j * (kind === 0 ? 0.06 : 0.16)) * RATE), len = Math.round((kind === 0 ? 0.045 : 0.12) * RATE);
        let p = 0;
        for (let i = 0; i < len && at + i < o.length; i++) {
          const x = i / len, f = kind === 2 ? f0 * (1.3 - 0.5 * x) : f0 * (1 + 0.25 * Math.sin(Math.PI * x)) * (1 + 0.1 * Math.sin(TAU * 30 * i / RATE));
          p += (TAU * f) / RATE;
          o[at + i] += Math.sin(p) * Math.sin(Math.PI * x) * 0.11;
        }
      }
    }
    return o;
  },
  breeze(sec, r) { // very soft, low wind bed (no hiss)
    const o = buf(sec);
    const lp = new Biquad('lp', 350), lp2 = new Biquad('lp', 250);
    for (let i = 0; i < o.length; i++) o[i] = lp2.run(lp.run(r.float(-1, 1))) * (0.7 + 0.3 * Math.sin(i / RATE / 2.3)) * 1.4;
    return o;
  },
  rain(sec, r) {
    const o = buf(sec);
    const lp = new Biquad('lp', 2500), hp = new Biquad('hp', 400);
    for (let i = 0; i < o.length; i++) o[i] = hp.run(lp.run(r.float(-1, 1))) * 0.25;
    for (let k = 0; k < sec * 25; k++) noiseBurst(o, Math.round(r.float(0, sec - 0.02) * RATE), 0.01, r.float(0.05, 0.2), r, [new Biquad('bp', r.float(2000, 6000), 2)]);
    return o;
  },
  thunder(sec, r) { // two rolls of thunder, timed with the lightning of the storm scene (stories/storm.js)
    const o = buf(sec);
    for (const at of [0.3, 0.72]) {
      const st = 0.2 + at * (sec - 0.4), lp = new Biquad('lp', 160), lp2 = new Biquad('lp', 700);
      const len = Math.min(o.length - Math.round(st * RATE), Math.round(2.6 * RATE));
      for (let i = 0; i < len; i++) {
        const x = i / RATE, env = Math.min(1, x / 0.03) * Math.exp(-x / 0.9) * (1 + 0.5 * Math.sin(x * 9 + r.float(0, 0.3)));
        const crack = x < 0.12 ? lp2.run(r.float(-1, 1)) * (1 - x / 0.12) : 0;
        o[Math.round(st * RATE) + i] += lp.run(r.float(-1, 1)) * env * 1.6 + crack * 0.8;
      }
    }
    return o;
  },
  howl(sec, r) { // one wolf howl in the middle of the wolves scene (stories/wolves.js), the pack answering softly
    const o = buf(sec);
    const voices = [[0.2 + 0.43 * (sec - 0.4), 1, 1], [0.2 + 0.52 * (sec - 0.4), 0.35, 1.12]];
    for (const [st, amp, k] of voices) {
      const len = Math.min(o.length - Math.round(st * RATE), Math.round(1.9 * RATE));
      let ph = 0;
      for (let i = 0; i < len; i++) {
        const x = i / len, f = k * (380 + 260 * Math.sin(Math.PI * Math.min(1, x * 1.6)) - 120 * x) * (1 + 0.012 * Math.sin(i / RATE * 34));
        ph += (TAU * f) / RATE;
        const env = Math.min(1, x * 8) * Math.min(1, (1 - x) * 4);
        o[Math.round(st * RATE) + i] += (Math.sin(ph) * 0.8 + Math.sin(2 * ph) * 0.15) * env * amp * 0.35;
      }
    }
    return o;
  },
  cheer(sec, r) { // a crowd cheering: many open "ah" voices swelling and falling, and clapping
    const o = buf(sec);
    for (let v = 0; v < 14; v++) {
      const f0 = r.float(140, 320), f1 = new Biquad('bp', r.float(700, 950), 4), f2 = new Biquad('bp', r.float(1100, 1500), 5);
      const st = r.float(0, 0.6), dur = r.float(1.2, 2.4);
      let ph = 0;
      for (let rep = st; rep < sec; rep += dur + r.float(0.2, 0.9)) {
        const i0 = Math.round(rep * RATE), len = Math.min(o.length - i0, Math.round(dur * RATE));
        for (let i = 0; i < len; i++) {
          const x = i / len, f = f0 * (1 + 0.25 * Math.sin(Math.PI * x)) * (1 + 0.02 * Math.sin(i / 900));
          ph += (TAU * f) / RATE;
          const src = (ph % TAU) / TAU - 0.5, env = Math.sin(Math.PI * Math.min(1, x * 1.2)) ** 0.7;
          o[i0 + i] += (f1.run(src) + 0.6 * f2.run(src)) * env * 0.16;
        }
      }
    }
    const hp = new Biquad('hp', 900);
    for (let k = 0; k < sec * 22; k++) noiseBurst(o, Math.round(r.float(0, sec - 0.05) * RATE), 0.03, r.float(0.1, 0.25), r, [hp]);
    return o;
  },
  baa(sec, r) { // sheep bleating now and then across the meadow
    const o = buf(sec);
    for (let at = r.float(0.2, 0.8); at < sec - 0.7; at += r.float(0.7, 1.6)) {
      const f0 = r.float(230, 380), dur = r.float(0.45, 0.7), bp = new Biquad('bp', r.float(900, 1300), 2.5);
      const i0 = Math.round(at * RATE), len = Math.min(o.length - i0, Math.round(dur * RATE)), gain = r.float(0.3, 0.6);
      let ph = 0;
      for (let i = 0; i < len; i++) {
        const x = i / len, vib = 1 + 0.06 * Math.sin(i / RATE * TAU * 11); // the quaver of a bleat
        ph += (TAU * f0 * vib * (1 - 0.1 * x)) / RATE;
        const src = ((ph / TAU) % 1) * 2 - 1;
        o[i0 + i] += bp.run(src) * Math.sin(Math.PI * Math.min(1, x * 1.3)) * gain;
      }
    }
    return o;
  },
  oink(sec, r) { // a pig grunting and squealing as it runs
    const o = buf(sec);
    for (let at = r.float(0.05, 0.3); at < sec - 0.3; at += r.float(0.25, 0.6)) {
      const squeal = r.chance(0.35), dur = squeal ? r.float(0.25, 0.4) : r.float(0.1, 0.18);
      const f0 = squeal ? r.float(700, 1000) : r.float(110, 170), bp = new Biquad('bp', squeal ? 1800 : 600, 3);
      const i0 = Math.round(at * RATE), len = Math.min(o.length - i0, Math.round(dur * RATE));
      let ph = 0;
      for (let i = 0; i < len; i++) {
        const x = i / len;
        ph += (TAU * f0 * (squeal ? 1 + 0.3 * Math.sin(Math.PI * x) : 1 - 0.2 * x)) / RATE;
        const src = ((ph / TAU) % 1) * 2 - 1 + r.float(-0.3, 0.3);
        o[i0 + i] += bp.run(src) * Math.sin(Math.PI * x) * (squeal ? 0.35 : 0.6);
      }
    }
    return o;
  },
  fanfare(sec, r) { // a short brass fanfare at the start (the King's arrival): G C E G, the last note held
    const o = buf(sec);
    const notes = [[392, 0.15, 0.2], [523.3, 0.38, 0.2], [659.3, 0.61, 0.2], [784, 0.84, 1.1]];
    for (const [f, at, dur] of notes) {
      const lp = new Biquad('lp', 2400), i0 = Math.round(at * RATE), len = Math.min(o.length - i0, Math.round(dur * RATE));
      let ph = 0;
      for (let i = 0; i < len; i++) {
        const x = i / RATE;
        ph += (TAU * f * (1 + (x > 0.25 ? 0.006 * Math.sin(x * 33) : 0))) / RATE;
        const saw = ((ph / TAU) % 1) * 2 - 1, env = Math.min(1, x / 0.03) * Math.min(1, (dur - x) / 0.06);
        o[i0 + i] += lp.run(saw) * env * 0.35;
      }
    }
    return o;
  },
  chime(sec, r) { // a soft bright chime for the call to action
    const o = buf(sec);
    [0, 0.12, 0.24].forEach((d, i) => modes(o, Math.round(d * RATE), [[[1318, 1568, 2093][i], 0.4, 0.6], [[1318, 1568, 2093][i] * 2, 0.1, 0.3]], 0.3, r));
    return o;
  },
};

/** A user recording from assets/audio/sfx/<name>.* if present (decoded to 48 kHz mono), else synthesized. */
function sound(name, sec, r, dir) {
  const file = ['wav', 'ogg', 'mp3', 'flac', 'm4a'].map((e) => path.resolve('assets/audio/sfx', `${name}.${e}`)).find((f) => fs.existsSync(f));
  if (file && dir) {
    const out = path.join(dir, `sfx_${name}.wav`);
    if (!fs.existsSync(out)) spawnSync('ffmpeg', ['-y', '-loglevel', 'error', '-i', file, '-ac', '1', '-ar', String(RATE), '-c:a', 'pcm_s16le', out]);
    if (fs.existsSync(out)) {
      const src = readWav(out).samples, o = buf(sec);
      const start = src.length > o.length ? Math.floor(r.float(0, src.length - o.length)) : 0;
      for (let i = 0; i < o.length; i++) o[i] = src[(start + i) % src.length];
      return o;
    }
  }
  return GEN[name](sec, r);
}

