/** One impact, synced to a strike in the animation (blacksmith, woodcutter, farmer, mason, guards training). */
function hit(kind, r) {
  const o = buf(kind === 'anvil' ? 0.9 : 0.4);
  if (kind === 'anvil') {
    const f = r.float(1050, 1180), a = r.float(0.4, 0.5);
    modes(o, 0, [[f, 0.5, 0.45], [f * 2.76, 0.32, 0.22], [f * 5.4, 0.18, 0.1], [f * 8.93, 0.1, 0.05], [f * 0.5, 0.15, 0.3]], a, r);
    noiseBurst(o, 0, 0.01, a, r, [new Biquad('hp', 3000)]);
  } else if (kind === 'chop') {
    modes(o, 0, [[r.float(170, 220), 0.7, 0.06], [r.float(420, 520), 0.4, 0.035]], 0.8, r);
    noiseBurst(o, 0, 0.03, 0.7, r, [new Biquad('bp', 1400, 1.1)]);
  } else if (kind === 'hoe') {
    modes(o, 0, [[r.float(95, 130), 0.6, 0.07]], 0.6, r);
    noiseBurst(o, 0, 0.09, 0.55, r, [new Biquad('lp', 900)]);
  } else if (kind === 'clang') { // two swords meeting: a short bright ring
    const f = r.float(1500, 1900);
    modes(o, 0, [[f, 0.5, 0.18], [f * 2.41, 0.35, 0.1], [f * 3.9, 0.2, 0.06], [f * 0.63, 0.25, 0.08]], 0.55, r);
    noiseBurst(o, 0, 0.012, 0.6, r, [new Biquad('hp', 2800)]);
  } else if (kind === 'straw') { // a blade into the straw dummy: a dull thump and a rustle
    modes(o, 0, [[r.float(110, 150), 0.6, 0.06]], 0.5, r);
    noiseBurst(o, 0, 0.12, 0.5, r, [new Biquad('bp', 2200, 0.8)]);
  } else if (kind === 'chisel') {
    modes(o, 0, [[r.float(2100, 2600), 0.4, 0.03], [r.float(5200, 6000), 0.2, 0.015]], 0.5, r);
    noiseBurst(o, 0, 0.015, 0.4, r, [new Biquad('hp', 2500)]);
  }
  return o;
}
const WORK_BEDS = { blacksmith: [['fire', 0.25]], toolsmith: [['fire', 0.25]], brewer: [['chatter', 0.3]], baker: [['fire', 0.3], ['chatter', 0.1]], fisherman: [['water', 0.5]], merchant: [['chatter', 0.3]], innkeeper: [['chatter', 0.3]], stonemason: [['stone', 0.2]],
  // the other scenes of a job (VARIANTS in src/render/scene/timeline.js)
  'carpenter:saw': [['saw', 0.5]], 'blacksmith:bellows': [['fire', 0.45]], 'toolsmith:bellows': [['fire', 0.45]],
  'baker:knead': [['chatter', 0.1]], 'brewer:stir': [['fire', 0.2], ['chatter', 0.1]], 'stonemason:stack': [['stone', 0.4]], 'miller:quern': [['stone', 0.15]] };

function sceneFor(cue) {
  if (cue.kind === 'house') return cue.rebuilt ? 'rebuilt' : 'house';
  if (cue.kind === 'loss') return 'loss';
  if (cue.kind === 'villager') return { inside: 'tavern', walls: 'patrol', wall2: 'patrol', sparring: 'sparring', boat: 'boat', rod: 'boat', net: 'boat', night: 'nightwatch', wallnight: 'nightwatch', wall2night: 'nightwatch', change: 'change', wall2change: 'change', pasture: 'pasture', wheat: 'wheat', laundry: 'laundry' }[cue.variant] ?? null; // work: synced strikes below
  if (cue.kind === 'caravan') return 'caravan';
  if (cue.kind === 'tavern') return 'tavern';
  if (cue.kind === 'church') return 'church';
  if (cue.kind === 'ambient') return SCENES[cue.id] ? cue.id : null; // the fields: hoe strikes below
  if (cue.kind === 'event') return ['ev_' + cue.id, 'ev_' + cue.id.split('_')[0]].find((k) => SCENES[k]) || 'story'; // a later step: its own bed or the story's
  if (cue.kind === 'castle' || cue.kind === 'gate') return 'castle';
  if (cue.kind === 'building' || cue.kind === 'story') {
    const id = (cue.id || '').startsWith('district') ? 'district' : cue.id;
    if (SCENES[id]) return cue.completed === false && !['dock', 'harbor', 'well'].includes(id) ? 'construction' : id;
    return cue.kind === 'story' ? 'story' : 'construction';
  }
  return null;
}

/**
 * Build the effects track. cues: [{kind, id, t0, t1, completed, rebuilt, pan}] from the renderer.
 * Returns the path of a 30 s stereo WAV.
 */
export function makeSfxTrack(file, { cues = [], seed, date, weather, duration = 30, workDir }) {
  const r = rng(seed, 'sfx', date);
  const N = Math.round(duration * RATE);
  const L = new Float32Array(N), R = new Float32Array(N);
  const place = (mono, t0, gain, pan = 0, fadeIn = 0.35, fadeOut = 0.45) => {
    const a = Math.round(t0 * RATE);
    const gl = gain * Math.cos(((pan + 1) * Math.PI) / 4), gr = gain * Math.sin(((pan + 1) * Math.PI) / 4);
    for (let i = 0; i < mono.length && a + i < N; i++) {
      if (a + i < 0) continue;
      const t = i / RATE, env = Math.min(1, t / fadeIn, (mono.length / RATE - t) / fadeOut);
      L[a + i] += mono[i] * env * gl;
      R[a + i] += mono[i] * env * gr;
    }
  };
  // quiet beds for the whole video
  place(sound('breeze', duration, r, workDir), 0, 0.05, 0, 1, 1);
  place(sound('birds', duration, r, workDir), 0, 0.22, 0.2, 1, 1);
  if (weather === 'rain') place(sound('rain', duration, r, workDir), 0, 0.35, 0, 1, 1);
  // hook: the drawbridge chain runs down and the bridge lands
  place(sound('chain', 1.7, r, workDir), 0.05, 0.3, 0.3, 0.1, 0.2);
  place(sound('thud', 0.8, r, workDir), 1.75, 0.55, 0.3, 0.005, 0.3);
  // the shots
  for (const cue of cues) {
    const scene = sceneFor(cue);
    if (!scene) continue;
    const len = cue.t1 - cue.t0 + 0.4;
    for (const [name, gain] of SCENES[scene]) place(sound(name, len, r, workDir), cue.t0 - 0.2, gain, cue.pan ?? 0);
    if (cue.kind === 'house') place(sound('thud', 0.8, r, workDir), cue.t0 + (cue.t1 - cue.t0) * 0.66, 0.35, cue.pan ?? 0, 0.005, 0.3);
  }
  for (const cue of cues.filter((c) => c.kind === 'villager' || (c.kind === 'ambient' && c.strikes?.length))) {
    const len = cue.t1 - cue.t0 + 0.4;
    for (const [name, gain] of WORK_BEDS[`${cue.job}:${cue.variant}`] || WORK_BEDS[cue.job] || []) place(sound(name, len, r, workDir), cue.t0 - 0.2, gain, cue.pan ?? 0);
    for (const ts of cue.strikes || []) place(hit(cue.strikeSound, r), ts - 0.005, cue.strikeSound === 'anvil' || cue.strikeSound === 'clang' ? 0.6 : 0.75, cue.pan ?? 0, 0.002, 0.3);
  }
  // wide shot: a distant bell if the kingdom has one; chains again as the bridge rises for the loop
  if (cues.some((c) => c.hasChapel)) place(sound('bell', 4.5, r, workDir), 23.9, 0.18, -0.3, 0.2, 1.2);
  place(sound('chime', 1.2, r, workDir), 27.1, 0.4, 0, 0.005, 0.5);
  place(sound('chain', 1.7, r, workDir), 28.2, 0.25, 0.3, 0.1, 0.4);
  // gentle limiter
  for (let i = 0; i < N; i++) { L[i] = Math.tanh(L[i] * 1.1) / 1.1; R[i] = Math.tanh(R[i] * 1.1) / 1.1; }
  writeWav(file, [L, R], RATE);
  return file;
}

export const SFX_NAMES = Object.keys(GEN);
